import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"FIR 滤波器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/fir/index.md","filePath":"v0.1.0-alpha/modules/fir/index.md"}'),r={name:"v0.1.0-alpha/modules/fir/index.md"};function i(l,t,c,h,n,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="fir-滤波器" tabindex="-1">FIR 滤波器 <a class="header-anchor" href="#fir-滤波器" aria-label="Permalink to &quot;FIR 滤波器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>fir</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>使用自己填写的有限抽头进行卷积。在不改变速率时，输出是当前及若干过去输入的加权和。它适合手工搭建移动平均、回声和简单差分滤波，直接研究抽头与响应的关系。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源.out → FIR 滤波器.in</code>，同时观察源输出与滤波结果。对于已有设计频率指标的任务，可先用低通等设计滤波器；需要直接指定系数时使用本模块。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>抽头按延迟顺序填写：第一项对应当前输入，后面的项对应更早的输入。等采样率时，<code>[0.5, 0.5]</code> 表示相邻两点平均，而 <code>[1, -1]</code> 表示一阶差分。</p><p>抽取／插值会改变速率与卷积的采样关系，不能再简单逐下标比较两端。原生标签延时声明只影响标签位置，不改变信号内容或 Master 时间轴，不能用它抵消波形延时。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>实数抽头 taps<br><code>taps</code></td><td><code>[1]</code></td><td>以逗号分隔有限实数，如 1, 0, 0.5。</td><td>可在线应用</td></tr><tr><td>抽取倍数<br><code>decimation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>插值倍数<br><code>interpolation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>原生标签延时声明<br><code>sample_delay</code></td><td><code>0</code></td><td>范围 0 至 2147483647；只改变 GNU 标签位置，不改变信号或 Master 时间轴；修改后重新准备。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>taps</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>抽头可以通过在线接口修改，但加长受本次准备的原生历史容量约束；失败时重新准备。速率关系和标签延时声明修改后需要重新准备。旧样本仍是旧抽头产生的结果。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><p>实数处理示例使用两抽头平均。观察输出比输入略有相位滞后，并与当前点和前一点的平均值比较；启动处要考虑此前没有完整输入历史。示例采用本机生成的正弦信号。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>填了系数但幅度变大？</strong> 抽头的和会影响直流增益，系数不会自动归一化。</p><p><strong>标签延时设大，曲线为什么没后移？</strong> 该字段声明标签位置，真正的信号延时来自抽头和延时器。</p>',28)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
